INSERT INTO posts (user_id, title, description, category, location_name, latitude, longitude, start_date, end_date, is_approved, images) VALUES

-- ========== 祭り (matsuri) ==========
('00000000-0000-0000-0000-000000000001', 'さぬき高松まつり2026', '高松市最大の夏祭り。三日間で約100万人が訪れる一大イベント。阿波踊り・よさこい・サンバと多彩な演舞が高松市街を埋め尽くす。', 'matsuri', '高松市中央通り', 34.3432, 134.0467, '2026-08-12', '2026-08-14', true, '{}'),
('00000000-0000-0000-0000-000000000001', '丸亀お城まつり2026', '丸亀城を舞台にした歴史と祭りの祭典。武者行列・太鼓演奏・屋台など盛りだくさん。夜はライトアップされた丸亀城が幻想的。', 'matsuri', '丸亀城', 34.2893, 133.7963, '2026-08-01', '2026-08-02', true, '{}'),
('00000000-0000-0000-0000-000000000001', '金刀比羅宮例大祭2026', 'こんぴらさん最大のお祭り。御神輿が785段の石段を下り、町を練り歩く勇壮な祭り。全国から多くの参拝者が訪れる。', 'matsuri', '金刀比羅宮・琴平町', 34.1853, 133.8227, '2026-10-09', '2026-10-11', true, '{}'),
('00000000-0000-0000-0000-000000000001', '観音寺まつり2026', '観音寺市の夏の風物詩。神輿・太鼓・踊りで市街地が活気づく。銭形砂絵の前でのステージイベントも見どころ。', 'matsuri', '観音寺市琴弾公園', 34.1267, 133.6612, '2026-07-24', '2026-07-25', true, '{}'),
('00000000-0000-0000-0000-000000000001', '善通寺まつり2026', '弘法大師の生誕地・善通寺で行われる伝統祭り。厳かな宗教行事と地域の祭りが融合した独自の文化を持つ。', 'matsuri', '善通寺', 34.2272, 133.7790, '2026-06-14', '2026-06-15', true, '{}'),
('00000000-0000-0000-0000-000000000001', '直島まつり2026', '瀬戸内の島、直島で行われる小さくても熱い祭り。島民手作りの演目と海辺のロケーションが魅力。', 'matsuri', '直島・本村地区', 34.4556, 133.9956, '2026-08-14', '2026-08-16', true, '{}'),
('00000000-0000-0000-0000-000000000001', '小豆島秋まつり2026', '小豆島各地の氏神を祀る秋の大祭。農村歌舞伎の奉納上演が有名で、国の重要無形民俗文化財にも指定されている。', 'matsuri', '小豆島・土庄町', 34.4881, 134.1804, '2026-10-15', '2026-10-19', true, '{}'),
('00000000-0000-0000-0000-000000000001', '高松城築城まつり2026', '高松城（玉藻公園）の歴史を称える祭り。甲冑武者の行列・弓道演武・茶会など、江戸時代の雰囲気が蘇る。', 'matsuri', '玉藻公園（高松城跡）', 34.3481, 134.0467, '2026-05-02', '2026-05-04', true, '{}'),
('00000000-0000-0000-0000-000000000001', '屋島ドラゴンバトル2026', '屋島の源平合戦ゆかりの地で行われる迫力のドラゴンボートレース。チームで息を合わせて太鼓の音に合わせて漕ぐ熱戦が見もの。', 'matsuri', '屋島西町海岸', 34.3681, 134.1027, '2026-09-06', '2026-09-06', true, '{}'),
('00000000-0000-0000-0000-000000000001', '土庄にぎわい祭り2026', '小豆島・土庄港周辺で行われる夏の祭典。海の幸グルメ・踊り・音楽ライブが盛りだくさん。', 'matsuri', '土庄港旅客ターミナル', 34.4881, 134.1804, '2026-08-07', '2026-08-08', true, '{}'),
('00000000-0000-0000-0000-000000000001', '三豊市ふるさと祭り2026', '三豊市合併20周年を記念した大型祭り。5地域の伝統文化が一堂に集まる貴重な機会。詫間・仁尾・高瀬などの郷土芸能も披露。', 'matsuri', '三豊市民体育館周辺', 34.1850, 133.7133, '2026-10-03', '2026-10-04', true, '{}'),
('00000000-0000-0000-0000-000000000001', 'さぬき市志度まつり2026', '藤原釈迦の出身地・志度で行われる秋祭り。勇壮なだんじりが町を練り歩き、海の安全を祈願する。', 'matsuri', 'さぬき市志度', 34.3248, 134.1801, '2026-10-10', '2026-10-11', true, '{}'),
('00000000-0000-0000-0000-000000000001', '宇多津ふるさとまつり2026', '宇多津町の夏の一大イベント。古い町並みを生かした趣のある祭り。塩の歴史にちなんだ展示やパレードも。', 'matsuri', '宇多津ゴールドタワー周辺', 34.3108, 133.8241, '2026-07-18', '2026-07-19', true, '{}'),
('00000000-0000-0000-0000-000000000001', '多度津まつり2026', '港町・多度津の秋祭り。威勢のいいだんじりが走り、太鼓の音が響き渡る。多度津藩ゆかりの歴史を感じさせる祭り。', 'matsuri', '多度津町中心部', 34.2744, 133.7494, '2026-10-14', '2026-10-15', true, '{}'),
('00000000-0000-0000-0000-000000000001', '東かがわ市引田まつり2026', '白壁の古い町並みが残る引田で行われる秋祭り。だんじりや神輿が歴史ある街道を練り歩く。', 'matsuri', '引田町並み保存地区', 34.2464, 134.3639, '2026-10-17', '2026-10-18', true, '{}'),
('00000000-0000-0000-0000-000000000001', '豊島まつり2026', '瀬戸内の豊島で行われる素朴で温かみのある島の祭り。島の農業と海の恵みへの感謝を込めた伝統行事。', 'matsuri', '豊島・唐櫃浜', 34.4836, 134.1537, '2026-08-15', '2026-08-16', true, '{}'),
('00000000-0000-0000-0000-000000000001', '女木島おにまつり2026', '鬼ヶ島（女木島）の鬼伝説にちなんだユニークな祭り。鬼のコスチュームで参加できるパレードが人気。', 'matsuri', '女木島鬼ヶ島大洞窟', 34.3827, 134.0828, '2026-10-31', '2026-10-31', true, '{}'),
('00000000-0000-0000-0000-000000000001', '坂出まつり2026', '坂出市の夏まつり。瀬戸大橋を望む港での花火と踊りが最大の見どころ。地元の太鼓グループも多数参加。', 'matsuri', '坂出市番の州公園', 34.3168, 133.8597, '2026-08-20', '2026-08-21', true, '{}'),
('00000000-0000-0000-0000-000000000001', '綾川夏まつり2026', '綾川町の田園地帯を舞台にした夏祭り。地元の伝統踊りと農産物の収穫を祝う行事。', 'matsuri', '綾川町役場周辺', 34.2494, 133.9393, '2026-08-01', '2026-08-01', true, '{}'),
('00000000-0000-0000-0000-000000000001', 'まんのう秋まつり2026', '満濃池のほとりで行われる収穫感謝の祭り。弘法大師が修築した満濃池をテーマにした歴史的な行事。', 'matsuri', '満濃池ふるさと公園', 34.1948, 133.8731, '2026-11-03', '2026-11-03', true, '{}'),
('00000000-0000-0000-0000-000000000001', '高松栗林公園春まつり2026', '特別名勝・栗林公園で行われる春の祭り。茶会・俳句会・吟詠など伝統文化を満喫できる。', 'matsuri', '栗林公園', 34.3286, 134.0487, '2026-03-21', '2026-04-05', true, '{}'),
('00000000-0000-0000-0000-000000000001', 'こんぴら春まつり2026', '金刀比羅宮の春の大祭。花嫁行列の再現や田植え祭りなど春ならではの行事が多数催される。', 'matsuri', '金刀比羅宮参道', 34.1853, 133.8227, '2026-04-10', '2026-04-12', true, '{}'),
('00000000-0000-0000-0000-000000000001', '仁尾いきいきまつり2026', '三豊市仁尾地区の活性化イベント。地元の特産品・マグロ・オリーブなどの食と伝統芸能が楽しめる。', 'matsuri', '仁尾海水浴場', 34.0938, 133.6543, '2026-08-09', '2026-08-09', true, '{}'),
('00000000-0000-0000-0000-000000000001', '塩飽諸島まつり2026', '江戸時代に海運で栄えた塩飽諸島・本島で行われる歴史ある祭り。伝統的な漁法の実演も見られる。', 'matsuri', '丸亀市本島', 34.3024, 133.7052, '2026-09-12', '2026-09-13', true, '{}'),
('00000000-0000-0000-0000-000000000001', '高松秋まつり2026', '高松市街で行われる秋の大型祭り。神輿・だんじり・よさこいが一堂に集まる迫力満点のイベント。', 'matsuri', '高松市丸亀町商店街', 34.3428, 134.0487, '2026-10-02', '2026-10-04', true, '{}'),
('00000000-0000-0000-0000-000000000001', '讃岐国分寺さぬきうどん祭り2026', '国の特別史跡・讃岐国分寺跡で行われる讃岐うどんをテーマにした祭り。打ちたて・茹でたてのうどんを堪能できる。', 'matsuri', '讃岐国分寺跡', 34.2694, 133.9623, '2026-05-16', '2026-05-17', true, '{}'),

-- ========== 屋台・食 (yatai) ==========
('00000000-0000-0000-0000-000000000001', 'さぬきうどんフェスタ2026', '讃岐うどんの有名店・人気店が一堂に集結。食べ比べ・打ち方体験・うどんアート展示など。香川に来たらまずここへ。', 'yatai', 'サンメッセ香川', 34.2897, 134.0034, '2026-05-02', '2026-05-05', true, '{}'),
('00000000-0000-0000-0000-000000000001', '高松港夕涼み縁日2026', '高松港フェリー乗り場周辺に屋台が並ぶ夏の夕涼みイベント。焼きそば・かき氷・金魚すくいなど定番屋台が勢揃い。瀬戸内の夕日を眺めながら楽しめる。', 'yatai', '高松港', 34.3498, 134.0517, '2026-07-17', '2026-08-31', true, '{}'),
('00000000-0000-0000-0000-000000000001', '丸亀城下グルメフェア2026', '丸亀城公園にグルメ屋台が集結。骨付鳥・讃岐うどん・地産地消グルメなど香川の味覚を一度に楽しめる。', 'yatai', '丸亀城公園', 34.2893, 133.7963, '2026-04-25', '2026-04-26', true, '{}'),
('00000000-0000-0000-0000-000000000001', '栗林公園夜市2026', '特別名勝・栗林公園の夜間開園に合わせた夜市。幻想的なライトアップの中、地元グルメや工芸品の露店が並ぶ。', 'yatai', '栗林公園', 34.3286, 134.0487, '2026-08-13', '2026-08-15', true, '{}'),
('00000000-0000-0000-0000-000000000001', '小豆島オリーブ収穫祭2026', '小豆島のオリーブ収穫時期に合わせたフードイベント。オリーブオイルを使った料理・オリーブソフト・搾りたてオイルの試食販売。', 'yatai', '小豆島オリーブ公園', 34.4609, 134.2024, '2026-10-10', '2026-10-18', true, '{}'),
('00000000-0000-0000-0000-000000000001', '高松中央商店街縁日市2026', 'アーケード商店街に屋台・露店が並ぶ週末縁日。地元農産物・手作り品・スイーツなど多彩な出店。', 'yatai', '高松丸亀町商店街', 34.3428, 134.0487, '2026-03-07', '2026-03-08', true, '{}'),
('00000000-0000-0000-0000-000000000001', '屋島寺門前市2026', '屋島寺の参道に地元農産物・骨董品・手作り工芸品の露店が並ぶ月1回の門前市。讃岐の郷土料理も楽しめる。', 'yatai', '屋島寺参道', 34.3924, 134.1128, '2026-04-05', '2026-04-05', true, '{}'),
('00000000-0000-0000-0000-000000000001', '観音寺港海鮮市2026', '燧灘で獲れた新鮮な魚介類を販売する海鮮市。焼き魚・海鮮丼の屋台も出店。漁師直売ならではの安さと鮮度。', 'yatai', '観音寺漁港', 34.1131, 133.6627, '2026-07-04', '2026-07-05', true, '{}'),
('00000000-0000-0000-0000-000000000001', '直島アート縁日2026', '直島の港周辺に地元アーティストのハンドメイド作品・島産食材の屋台が並ぶ。アートと食を楽しむ島時間。', 'yatai', '直島宮浦港', 34.4612, 133.9956, '2026-05-03', '2026-05-05', true, '{}'),
('00000000-0000-0000-0000-000000000001', '琴平温泉まちあるきグルメ2026', 'こんぴら参りのあとに立ち寄りたいグルメイベント。参道・温泉街に地元名物の屋台が出て食べ歩きを楽しめる。', 'yatai', '琴平温泉街', 34.1853, 133.8227, '2026-11-07', '2026-11-08', true, '{}'),
('00000000-0000-0000-0000-000000000001', 'さぬき市骨付鳥グランプリ2026', '讃岐名物・骨付鳥の食べ比べイベント。県内の名店が集まり、来場者投票でナンバーワンを決定する。', 'yatai', 'さぬき市総合公園', 34.3248, 134.1801, '2026-09-19', '2026-09-20', true, '{}'),
('00000000-0000-0000-0000-000000000001', '高松ワインフェスタ2026', '瀬戸内の食材と国内外のワインを楽しむフードフェスタ。高松港近くの会場でシェフが腕を振るうスペシャルメニューも。', 'yatai', '高松港レトロ街区', 34.3498, 134.0517, '2026-11-14', '2026-11-15', true, '{}'),
('00000000-0000-0000-0000-000000000001', '丸亀うちわ市2026', '日本一のうちわ産地・丸亀の夏まつり。うちわ販売と合わせて地元グルメ屋台も多数出店。うちわ絵付け体験も楽しめる。', 'yatai', '丸亀市中心商店街', 34.2840, 133.7976, '2026-07-11', '2026-07-13', true, '{}'),
('00000000-0000-0000-0000-000000000001', '東かがわ手袋まつり市2026', '日本最大の手袋産地・東かがわ市の産業まつり。手袋の格安販売と並んでグルメ屋台が並ぶ地域の大イベント。', 'yatai', '東かがわ市中央公園', 34.2464, 134.3639, '2026-11-21', '2026-11-22', true, '{}'),
('00000000-0000-0000-0000-000000000001', '高松クラフトビアフェスト2026', '地元醸造所を中心にクラフトビールと地産食材を楽しむビアガーデン。瀬戸内の海を眺めながら最高の一杯を。', 'yatai', '高松サンポート合同庁舎周辺', 34.3520, 134.0476, '2026-09-05', '2026-09-06', true, '{}'),
('00000000-0000-0000-0000-000000000001', 'まんのう公園春の農産物市2026', '国営讃岐まんのう公園で開催される地元農産物の直売市。新鮮野菜・花苗・加工品の販売と同時に食べ歩き屋台も。', 'yatai', '国営讃岐まんのう公園', 34.1948, 133.8731, '2026-05-02', '2026-05-06', true, '{}'),
('00000000-0000-0000-0000-000000000001', '塩江温泉湯の里市場2026', '高松市奥座敷・塩江温泉で開かれる朝市。山の幸・川魚・温泉まんじゅうなど素朴な山里のグルメが揃う。', 'yatai', '塩江温泉郷', 34.2447, 134.0963, '2026-07-18', '2026-07-20', true, '{}'),
('00000000-0000-0000-0000-000000000001', '坂出名物グルメ横丁2026', '瀬戸大橋の麓・坂出で開催されるグルメイベント。地元の練り物・ちくわ・海鮮など讃岐の食材を使った料理が勢揃い。', 'yatai', '坂出駅前広場', 34.3234, 133.8613, '2026-06-06', '2026-06-07', true, '{}'),
('00000000-0000-0000-0000-000000000001', '豊島産直マルシェ2026', '豊島の農家・漁師が直接販売する朝市。小さな島ならではの規模感と温かみ。レモン・ミカン・新鮮な海の幸が人気。', 'yatai', '豊島家浦港', 34.4836, 134.1537, '2026-05-30', '2026-05-31', true, '{}'),
('00000000-0000-0000-0000-000000000001', '高松天神前夜市2026', '高松天満宮の縁日に合わせた夜市。地元の若手出店者が多く、個性豊かなグルメや雑貨が並ぶ。', 'yatai', '高松天満宮', 34.3411, 134.0612, '2026-08-25', '2026-08-25', true, '{}'),
('00000000-0000-0000-0000-000000000001', '善通寺いちご狩り&フェア2026', '弘法大師生誕地・善通寺周辺のいちご農園と連携した春のイベント。いちご狩り・スイーツ屋台・ジャム販売。', 'yatai', '善通寺市中心部', 34.2272, 133.7790, '2026-03-14', '2026-03-22', true, '{}'),

-- ========== 花火 (hanabi) ==========
('00000000-0000-0000-0000-000000000001', 'さぬき高松まつり花火大会2026', '高松港を舞台に打ち上げられる圧巻の花火。毎年2万発を超える花火が瀬戸内の夜空を彩る香川県最大の花火大会。', 'hanabi', '高松港', 34.3498, 134.0517, '2026-08-13', '2026-08-13', true, '{}'),
('00000000-0000-0000-0000-000000000001', '丸亀花火大会2026', '丸亀港で行われる夏の夜の風物詩。水中花火や仕掛け花火など趣向を凝らした演出が好評。家族連れに人気の花火大会。', 'hanabi', '丸亀港', 34.2843, 133.7891, '2026-08-01', '2026-08-01', true, '{}'),
('00000000-0000-0000-0000-000000000001', '観音寺市花火大会2026', '琴弾公園・有明浜から打ち上げられる花火大会。砂浜に描かれた巨大な銭形砂絵と花火のコラボレーションが幻想的。', 'hanabi', '有明浜・琴弾公園', 34.1267, 133.6612, '2026-07-26', '2026-07-26', true, '{}'),
('00000000-0000-0000-0000-000000000001', '宇多津花火大会2026', '宇多津ゴールドタワー前の海上から打ち上げる花火大会。海面に映る花火が美しく「水上花火」の演出もある。', 'hanabi', '宇多津海岸', 34.3061, 133.8267, '2026-08-15', '2026-08-15', true, '{}'),
('00000000-0000-0000-0000-000000000001', '坂出みなと花火大会2026', '瀬戸大橋をバックに打ち上げられる花火大会。橋のライトアップと花火のコラボが絶景。', 'hanabi', '坂出港', 34.3114, 133.8579, '2026-08-22', '2026-08-22', true, '{}'),
('00000000-0000-0000-0000-000000000001', '小豆島土庄花火大会2026', '小豆島・土庄港で打ち上げられる島の夏の風物詩。海上から打ち上げられる花火と島の夜景が美しく調和する。', 'hanabi', '土庄港海岸', 34.4881, 134.1804, '2026-08-14', '2026-08-14', true, '{}'),
('00000000-0000-0000-0000-000000000001', '東かがわ白鳥花火大会2026', '白鳥神社の夏祭りに合わせた花火大会。歴史ある神社と花火の組み合わせが趣深い。', 'hanabi', '東かがわ市白鳥海岸', 34.2589, 134.3178, '2026-08-08', '2026-08-08', true, '{}'),
('00000000-0000-0000-0000-000000000001', '直島ナイトフェスタ花火2026', '直島のアートな雰囲気の中で打ち上げられる小規模ながら幻想的な花火。島全体が一体となって楽しむ特別な夜。', 'hanabi', '直島宮浦海岸', 34.4612, 133.9956, '2026-08-16', '2026-08-16', true, '{}'),
('00000000-0000-0000-0000-000000000001', '三豊市仁尾花火大会2026', '三豊市仁尾地区の夏の風物詩。漁港から打ち上げられる花火と漁火が幻想的な夜景を作り出す。', 'hanabi', '仁尾漁港', 34.0938, 133.6543, '2026-08-08', '2026-08-08', true, '{}'),
('00000000-0000-0000-0000-000000000001', 'まんのう公園夏の花火2026', '国営讃岐まんのう公園の芝生広場から打ち上げる花火。広大な公園でゆったりとレジャーシートを広げて楽しめる。', 'hanabi', '国営讃岐まんのう公園', 34.1948, 133.8731, '2026-08-22', '2026-08-22', true, '{}'),
('00000000-0000-0000-0000-000000000001', '多度津港花火大会2026', '多度津港から打ち上げられる花火大会。瀬戸内の島々を背景に打ち上がる花火は格別の美しさ。', 'hanabi', '多度津漁港', 34.2678, 133.7512, '2026-08-01', '2026-08-01', true, '{}'),
('00000000-0000-0000-0000-000000000001', '高松レインボー花火2026', '高松市制130周年を記念した特別花火大会。カラフルな演出と大型スターマインで夜空を彩る。', 'hanabi', '高松サンポート', 34.3520, 134.0476, '2026-11-03', '2026-11-03', true, '{}'),

-- ========== イベント (event) ==========
('00000000-0000-0000-0000-000000000001', '瀬戸内国際芸術祭2026春会期', '3年に1度の瀬戸内国際芸術祭（トリエンナーレ）の春会期。直島・豊島・女木島・男木島など12の島と2つの港で世界的アーティストの作品を展示。', 'event', '高松港・瀬戸内12島', 34.3498, 134.0517, '2026-04-18', '2026-05-10', true, '{}'),
('00000000-0000-0000-0000-000000000001', '瀬戸内国際芸術祭2026夏会期', '瀬戸内国際芸術祭の夏会期。夏限定のアートプログラムや島ならではの体験型展示が追加される。', 'event', '瀬戸内・各島', 34.4556, 133.9956, '2026-07-18', '2026-08-31', true, '{}'),
('00000000-0000-0000-0000-000000000001', '瀬戸内国際芸術祭2026秋会期', '瀬戸内国際芸術祭の秋会期。全会期の締めくくりとなる秋会期は特に来場者が多く、各島が賑わいのピークを迎える。', 'event', '高松港・各島', 34.3498, 134.0517, '2026-10-01', '2026-11-08', true, '{}'),
('00000000-0000-0000-0000-000000000001', 'こんぴら歌舞伎大芝居2026', '金丸座（旧金毘羅大芝居）で行われる本格歌舞伎公演。江戸時代の芝居小屋で観る歌舞伎は格別。全国から歌舞伎ファンが訪れる。', 'event', '旧金毘羅大芝居（金丸座）', 34.1853, 133.8227, '2026-04-04', '2026-04-23', true, '{}'),
('00000000-0000-0000-0000-000000000001', '高松国際ピアノコンクール2026', '全国から若手ピアニストが集まる高松の音楽の祭典。予選・本選と段階的に開催され、クラシック音楽ファン必見のイベント。', 'event', '高松市民会館', 34.3389, 134.0456, '2026-07-25', '2026-08-02', true, '{}'),
('00000000-0000-0000-0000-000000000001', 'さぬき映画祭2026', '香川の映像文化を盛り上げる映画祭。地元ゆかりの作品上映・監督トークショー・ショートフィルムコンペティションを開催。', 'event', '高松市内各映画館', 34.3432, 134.0467, '2026-03-14', '2026-03-22', true, '{}'),
('00000000-0000-0000-0000-000000000001', '高松マラソン2026', '高松の市街地と海沿いを走るフルマラソン。瀬戸内の風景を楽しみながら走れる人気の市民マラソン大会。', 'event', '高松市中心部（サンポートスタート）', 34.3520, 134.0476, '2026-03-01', '2026-03-01', true, '{}'),
('00000000-0000-0000-0000-000000000001', '小豆島オリーブマラソン2026', '小豆島の美しい海岸線とオリーブ畑を走るハーフマラソン。参加者にはオリーブオイルのプレゼントも。', 'event', '小豆島・土庄港', 34.4881, 134.1804, '2026-11-08', '2026-11-08', true, '{}'),
('00000000-0000-0000-0000-000000000001', '直島アートキャンプ2026', '直島に滞在しながらアート制作を体験するワークショップイベント。プロのアーティストから直接指導を受けられる。', 'event', '直島・本村エリア', 34.4556, 133.9956, '2026-08-07', '2026-08-10', true, '{}'),
('00000000-0000-0000-0000-000000000001', '讃岐うどん打ち選手権2026', '職人からアマチュアまでが参加するうどん打ちコンテスト。早さ・麺の出来・コシなど複数部門で競う。観客参加型のうどん試食会も。', 'event', 'サンメッセ香川', 34.2897, 134.0034, '2026-11-21', '2026-11-22', true, '{}'),
('00000000-0000-0000-0000-000000000001', '高松港アートウィーク2026', '高松港周辺のギャラリーや屋外スペースを使ったアートウィーク。地元アーティストから国際的なアーティストまで幅広い作品展示。', 'event', '高松港周辺', 34.3498, 134.0517, '2026-06-06', '2026-06-14', true, '{}'),
('00000000-0000-0000-0000-000000000001', 'かがわ農業祭2026', '香川県の農産物・特産品の魅力を発信する農業イベント。讃岐の野菜・果物・加工食品の展示販売と農業体験コーナー。', 'event', '香川県農業試験場', 34.2694, 133.9623, '2026-10-31', '2026-11-01', true, '{}'),
('00000000-0000-0000-0000-000000000001', '丸亀国際ハーフマラソン2026', '丸亀市内を走る国際大会レベルのハーフマラソン。日本国内トップランナーも参加する本格的な市民マラソン大会。', 'event', '丸亀競技場', 34.2927, 133.7845, '2026-02-01', '2026-02-01', true, '{}'),
('00000000-0000-0000-0000-000000000001', 'せとうちJAZZフェスティバル2026', '高松の夜を彩るジャズフェスティバル。市内各所のライブハウス・カフェ・屋外ステージで国内外のジャズミュージシャンが演奏。', 'event', '高松市内各会場', 34.3432, 134.0467, '2026-10-17', '2026-10-18', true, '{}'),
('00000000-0000-0000-0000-000000000001', '豊島音楽祭2026', '豊島の棚田や海辺を会場にした野外音楽フェスティバル。自然の中で聴く音楽は格別。アートの島ならではのユニークな演出も。', 'event', '豊島・棚田エリア', 34.4836, 134.1537, '2026-09-19', '2026-09-20', true, '{}'),
('00000000-0000-0000-0000-000000000001', '高松大茶会2026', '栗林公園を舞台にした大規模な野点（のだて）茶会。複数の流派が参加し、秋の庭園で一服のお茶を楽しむ。', 'event', '栗林公園', 34.3286, 134.0487, '2026-11-07', '2026-11-08', true, '{}'),
('00000000-0000-0000-0000-000000000001', '讃岐かがわ産業大博覧会2026', '香川県の伝統産業・観光・食文化を紹介する大型展示会。手袋・うちわ・しょう油など讃岐の名産品が勢揃い。', 'event', 'サンメッセ香川', 34.2897, 134.0034, '2026-05-30', '2026-05-31', true, '{}'),
('00000000-0000-0000-0000-000000000001', '島旅フォトコンテスト展示会2026', '瀬戸内の島々を撮影した写真の展示会。一般から募集した瀬戸内アイランドの美しい写真が高松港ギャラリーに並ぶ。', 'event', '高松港ターミナルビル', 34.3498, 134.0517, '2026-01-17', '2026-02-08', true, '{}'),
('00000000-0000-0000-0000-000000000001', '瀬戸大橋開通記念マラニック2026', '瀬戸大橋開通を記念した42.195kmのマラニック（マラソン＋ピクニック）イベント。橋を徒歩で渡れる特別な機会。', 'event', '坂出市・瀬戸大橋記念公園', 34.3168, 133.8597, '2026-04-10', '2026-04-12', true, '{}'),
('00000000-0000-0000-0000-000000000001', '高松ランタンフェスティバル2026', '台湾のランタン祭りにインスパイアされた幻想的なイベント。高松港から無数のランタンが夜空に舞い上がる。', 'event', '高松港', 34.3498, 134.0517, '2026-02-14', '2026-02-14', true, '{}'),
('00000000-0000-0000-0000-000000000001', '女木島トレッキングフェスタ2026', '鬼ヶ島として知られる女木島をトレッキングするイベント。島の絶景を楽しみながら全長約5kmのコースを歩く。', 'event', '女木島', 34.3827, 134.0828, '2026-04-18', '2026-04-19', true, '{}'),
('00000000-0000-0000-0000-000000000001', 'まんのう公園チューリップフェア2026', '国営讃岐まんのう公園に100万本のチューリップが咲き誇る春の風物詩。色とりどりのチューリップ畑は圧巻の美しさ。', 'event', '国営讃岐まんのう公園', 34.1948, 133.8731, '2026-03-28', '2026-04-19', true, '{}'),
('00000000-0000-0000-0000-000000000001', 'かがわサイクリングフェスタ2026', '瀬戸内の美しい風景の中を自転車で走るサイクリングイベント。高松〜丸亀〜小豆島など複数のコースが設定される。', 'event', '高松サンポートスタート', 34.3520, 134.0476, '2026-10-24', '2026-10-25', true, '{}'),
('00000000-0000-0000-0000-000000000001', '高松城下町ライトアップ2026', '高松城（玉藻公園）と周辺の歴史的建造物が幻想的にライトアップされる秋の夜のイベント。', 'event', '玉藻公園（高松城跡）', 34.3481, 134.0467, '2026-10-23', '2026-11-03', true, '{}'),
('00000000-0000-0000-0000-000000000001', '讃岐高校生バンドフェスティバル2026', '香川県内の高校生バンドが競い合う音楽フェスティバル。次世代の音楽シーンを担う若者たちの熱い演奏に注目。', 'event', '高松市民会館', 34.3389, 134.0456, '2026-09-13', '2026-09-13', true, '{}'),
('00000000-0000-0000-0000-000000000001', 'しまなみ・さぬきアイランドホッピング2026', '瀬戸内の島々を船でめぐるツアー型イベント。各島のアート・グルメ・自然を満喫できる特別プログラム。', 'event', '高松港（集合）', 34.3498, 134.0517, '2026-05-16', '2026-05-17', true, '{}'),
('00000000-0000-0000-0000-000000000001', '坂出瀬戸大橋マラソン2026', '瀬戸大橋を渡るコースを含む特別なマラソン大会。四国と本州をつなぐ橋を自分の足で走る夢のような体験。', 'event', '坂出・瀬戸大橋記念公園', 34.3168, 133.8597, '2026-11-15', '2026-11-15', true, '{}'),
('00000000-0000-0000-0000-000000000001', '高松モーターショー&カスタムカーフェスタ2026', '香川・四国最大のカーイベント。国内外の最新車種の展示と地元のカスタムカー・クラシックカーが一堂に集まる。', 'event', 'サンメッセ香川', 34.2897, 134.0034, '2026-03-21', '2026-03-22', true, '{}');
